CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,normalized_name text NOT NULL,domain text UNIQUE,address text,phone text,website text,google_place_id text,status text NOT NULL DEFAULT 'DISCOVERED',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),email text,phone text,kind text,source_url text,verified boolean NOT NULL DEFAULT false,invalid boolean NOT NULL DEFAULT false,UNIQUE(company_id,email));
CREATE TABLE IF NOT EXISTS social_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),network text NOT NULL,url text NOT NULL,UNIQUE(company_id,network,url));
CREATE TABLE IF NOT EXISTS sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies(id),source_type text NOT NULL,url text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),source_type text NOT NULL,source_url text NOT NULL,title text NOT NULL,excerpt text NOT NULL,signal_type text NOT NULL,confidence integer NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,source_url,excerpt));
CREATE TABLE IF NOT EXISTS search_queries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid,source text NOT NULL,query text NOT NULL,results_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS qualifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),fit integer NOT NULL,need integer NOT NULL,geography integer NOT NULL,contact_quality integer NOT NULL,recency integer NOT NULL,total integer NOT NULL,confidence text NOT NULL,decision text NOT NULL,reasoning text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,status text NOT NULL); CREATE TABLE IF NOT EXISTS message_sequences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),status text NOT NULL,next_step text,next_run_at timestamptz,human_response boolean NOT NULL DEFAULT false); CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),sequence_id uuid REFERENCES message_sequences(id),direction text NOT NULL,to_email text,subject text,body text NOT NULL,gmail_message_id text,gmail_thread_id text,sent_at timestamptz,idempotency_key text,outbound_state text NOT NULL DEFAULT 'DRAFT'); CREATE TABLE IF NOT EXISTS replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id),message_id uuid REFERENCES messages(id),gmail_message_id text,body text NOT NULL,classification text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppressions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text,domain text,company_id uuid REFERENCES companies(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 5,run_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,finished_at timestamptz,last_error text); CREATE TABLE IF NOT EXISTS runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'); CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action text NOT NULL,company_id uuid,job_id uuid,run_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS configuration(key text PRIMARY KEY,value text NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_ready_idx ON jobs(status,run_at); CREATE INDEX IF NOT EXISTS evidence_company_idx ON evidence(company_id); CREATE INDEX IF NOT EXISTS audit_company_idx ON audit_events(company_id);
